package com.kelompok4.oralhealthplus.data.local

import android.content.Context
import android.content.SharedPreferences
import com.kelompok4.oralhealthplus.feature.auth.GuestQuotaState
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

// Generated by Local AI (qwen2.5-coder:7b)
class SessionManager(context: Context) {
    private val sharedPreferences: SharedPreferences = context.getSharedPreferences("oralhealth_session", Context.MODE_PRIVATE)

    private val _loggedInUsernameFlow = MutableStateFlow(sharedPreferences.getString("username", null))
    val loggedInUsernameFlow: StateFlow<String?> = _loggedInUsernameFlow.asStateFlow()

    private val _displayNameFlow = MutableStateFlow(sharedPreferences.getString("displayName", "") ?: "")
    val displayNameFlow: StateFlow<String> = _displayNameFlow.asStateFlow()

    private val _profilePhotoPathFlow = MutableStateFlow(sharedPreferences.getString("profilePhotoPath", "") ?: "")
    val profilePhotoPathFlow: StateFlow<String> = _profilePhotoPathFlow.asStateFlow()

    private val _guestScanCountFlow = MutableStateFlow(sharedPreferences.getInt(KEY_GUEST_SCAN_COUNT, 0))
    val guestScanCountFlow: StateFlow<Int> = _guestScanCountFlow.asStateFlow()

    private val _guestAnalysisCountFlow = MutableStateFlow(sharedPreferences.getInt(KEY_GUEST_ANALYSIS_COUNT, 0))
    val guestAnalysisCountFlow: StateFlow<Int> = _guestAnalysisCountFlow.asStateFlow()

    private val _guestChatCountFlow = MutableStateFlow(sharedPreferences.getInt(KEY_GUEST_CHAT_COUNT, 0))
    val guestChatCountFlow: StateFlow<Int> = _guestChatCountFlow.asStateFlow()

    fun saveSession(
        username: String,
        displayName: String,
        authProvider: String = "LOCAL",
        email: String = "",
        whatsappNumber: String = "",
        profilePhotoPath: String = ""
    ) {
        with(sharedPreferences.edit()) {
            putString("username", username)
            putString("displayName", displayName)
            putString("authProvider", authProvider)
            putString("email", email)
            putString("whatsappNumber", whatsappNumber)
            putString("profilePhotoPath", profilePhotoPath)
            apply()
        }
        _loggedInUsernameFlow.value = username
        _displayNameFlow.value = displayName
        _profilePhotoPathFlow.value = profilePhotoPath
    }

    fun isLoggedIn(): Boolean {
        return sharedPreferences.getString("username", null) != null
    }

    fun getLoggedInUsername(): String? {
        return sharedPreferences.getString("username", null)
    }

    fun getDisplayName(): String {
        return sharedPreferences.getString("displayName", "") ?: ""
    }

    fun getAuthProvider(): String {
        return sharedPreferences.getString("authProvider", "LOCAL") ?: "LOCAL"
    }

    fun getEmail(): String {
        return sharedPreferences.getString("email", "") ?: ""
    }

    fun getWhatsappNumber(): String {
        return sharedPreferences.getString("whatsappNumber", "") ?: ""
    }

    fun getProfilePhotoPath(): String {
        return sharedPreferences.getString("profilePhotoPath", "") ?: ""
    }

    fun clearSession() {
        with(sharedPreferences.edit()) {
            remove("username")
            remove("displayName")
            remove("authProvider")
            remove("email")
            remove("whatsappNumber")
            remove("profilePhotoPath")
            apply()
        }
        _loggedInUsernameFlow.value = null
        _displayNameFlow.value = ""
        _profilePhotoPathFlow.value = ""
    }

    // --- Guest Quota Persistence (1x Scan, 1x Analysis, 3x Chatbot Questions) ---

    fun getGuestScanCount(): Int = sharedPreferences.getInt(KEY_GUEST_SCAN_COUNT, 0)

    fun getGuestAnalysisCount(): Int = sharedPreferences.getInt(KEY_GUEST_ANALYSIS_COUNT, 0)

    fun getGuestChatCount(): Int = sharedPreferences.getInt(KEY_GUEST_CHAT_COUNT, 0)

    fun recordGuestScan() {
        if (isLoggedIn()) return
        val next = getGuestScanCount() + 1
        sharedPreferences.edit().putInt(KEY_GUEST_SCAN_COUNT, next).apply()
        _guestScanCountFlow.value = next
    }

    fun recordGuestAnalysis() {
        if (isLoggedIn()) return
        val nextAnalysis = getGuestAnalysisCount() + 1
        val nextScan = maxOf(getGuestScanCount(), nextAnalysis)
        sharedPreferences.edit()
            .putInt(KEY_GUEST_ANALYSIS_COUNT, nextAnalysis)
            .putInt(KEY_GUEST_SCAN_COUNT, nextScan)
            .apply()
        _guestAnalysisCountFlow.value = nextAnalysis
        _guestScanCountFlow.value = nextScan
    }

    fun recordGuestChatQuestion() {
        if (isLoggedIn()) return
        val next = getGuestChatCount() + 1
        sharedPreferences.edit().putInt(KEY_GUEST_CHAT_COUNT, next).apply()
        _guestChatCountFlow.value = next
    }

    fun getGuestQuotaState(): GuestQuotaState = GuestQuotaState(
        isLoggedIn = isLoggedIn(),
        scanCount = getGuestScanCount(),
        analysisCount = getGuestAnalysisCount(),
        chatQuestionCount = getGuestChatCount()
    )

    companion object {
        private const val KEY_GUEST_SCAN_COUNT = "guest_scan_count"
        private const val KEY_GUEST_ANALYSIS_COUNT = "guest_analysis_count"
        private const val KEY_GUEST_CHAT_COUNT = "guest_chat_count"
    }

    // --- Chatbot Security Gate & Suspension Persistence ---

    fun getSecurityGateState(username: String): com.kelompok4.oralhealthplus.feature.chatbot.SecurityGateState {
        val userPrefix = "sec_${username.lowercase()}_"
        return com.kelompok4.oralhealthplus.feature.chatbot.SecurityGateState(
            lastMessageTimestamp = sharedPreferences.getLong("${userPrefix}last_ts", 0L),
            violationCount = sharedPreferences.getInt("${userPrefix}violation_count", 0),
            suspensionLevel = sharedPreferences.getInt("${userPrefix}suspension_level", 0),
            suspensionUntil = sharedPreferences.getLong("${userPrefix}suspension_until", 0L)
        )
    }

    fun saveSecurityGateState(username: String, state: com.kelompok4.oralhealthplus.feature.chatbot.SecurityGateState) {
        val userPrefix = "sec_${username.lowercase()}_"
        with(sharedPreferences.edit()) {
            putLong("${userPrefix}last_ts", state.lastMessageTimestamp)
            putInt("${userPrefix}violation_count", state.violationCount)
            putInt("${userPrefix}suspension_level", state.suspensionLevel)
            putLong("${userPrefix}suspension_until", state.suspensionUntil)
            apply()
        }
    }

    fun clearSecurityGateState(username: String) {
        val userPrefix = "sec_${username.lowercase()}_"
        with(sharedPreferences.edit()) {
            remove("${userPrefix}last_ts")
            remove("${userPrefix}violation_count")
            remove("${userPrefix}suspension_level")
            remove("${userPrefix}suspension_until")
            apply()
        }
    }
}
